with parsed as (select id, plan, tier_limits, array_min(tier_prices) as lowest_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price from price_tiers where plan not in ('starter', 'enterprise')) select plan, count(distinct plan) as distinct_plans, sum(avg_tier_price) as total_avg_tier_price, count(distinct id) as distinct_ids from parsed group by plan order by total_avg_tier_price desc
